14	TEST(StationCatalogTest, BuildStationListProjection_PreservesStationFields) {
15	  StationCatalog catalog;
16	  catalog.stations.push_back(Station{"receiving", "map", 1.0, 2.0, 0.25});
17	  catalog.stations.push_back(Station{"storage", "odom", -3.0, 4.5, -1.5});
18	
19	  const auto projection = BuildStationListProjection(catalog);
20	
21	  EXPECT_EQ(projection.station_ids, (std::vector<std::string>{"receiving", "storage"}));
22	  EXPECT_EQ(projection.frame_ids, (std::vector<std::string>{"map", "odom"}));
23	  EXPECT_EQ(projection.x, (std::vector<double>{1.0, -3.0}));
24	  EXPECT_EQ(projection.y, (std::vector<double>{2.0, 4.5}));
25	  EXPECT_EQ(projection.yaw, (std::vector<double>{0.25, -1.5}));
26	  EXPECT_EQ(projection.message, "loaded 2 station(s)");
27	}
