29	TEST(StationCatalogTest, BuildStationRouteListProjection_PreservesRouteFields) {
30	  StationCatalog catalog;
31	  catalog.edges.push_back(CatalogStationEdge{"receiving", "storage", 5.5, true, true});
32	  catalog.edges.push_back(CatalogStationEdge{"storage", "dock", 2.0, false, false});
33	
34	  const auto projection = BuildStationRouteListProjection(catalog);
35	
36	  EXPECT_EQ(projection.from_station, (std::vector<std::string>{"receiving", "storage"}));
37	  EXPECT_EQ(projection.to_station, (std::vector<std::string>{"storage", "dock"}));
38	  EXPECT_EQ(projection.distance_m, (std::vector<double>{5.5, 2.0}));
39	  EXPECT_EQ(projection.bidirectional, (std::vector<bool>{true, false}));
40	  EXPECT_EQ(projection.enabled, (std::vector<bool>{true, false}));
41	  EXPECT_EQ(projection.message, "loaded 2 route edge(s)");
42	}
