72	// 构造即完成初始加载（等价节点 on_configure 的一次性读取）。
73	TEST(StationCatalogReloaderTest, LoadsInitialCatalog) {
74	  auto p = WriteCatalogTemp(kTwoStations);
75	  amr_dispatcher_core::catalog::StationCatalogReloader reloader(p);
76	  EXPECT_TRUE(reloader.loaded());
77	  EXPECT_EQ(reloader.catalog().stations.size(), 2u);
78	  EXPECT_FALSE(reloader.Tick());  // mtime 未变，不触发重载
79	  std::remove(p.c_str());
80	}
