82	// mtime 变化触发重载换新；schema 非法时保留旧目录不清空。
83	TEST(StationCatalogReloaderTest, ReloadsOnMtimeChangeAndKeepsOldOnInvalid) {
84	  auto p = WriteCatalogTemp(kTwoStations);
85	  amr_dispatcher_core::catalog::StationCatalogReloader reloader(p);
86	  ASSERT_TRUE(reloader.loaded());
87	
88	  std::this_thread::sleep_for(std::chrono::milliseconds(20));  // 跨过文件系统 mtime 粒度
89	  {
90	    std::ofstream out(p, std::ios::trunc);
91	    out << kThreeStations;
92	  }
93	  EXPECT_TRUE(reloader.Tick());
94	  EXPECT_EQ(reloader.catalog().stations.size(), 3u);
95	
96	  std::this_thread::sleep_for(std::chrono::milliseconds(20));
97	  {
98	    std::ofstream out(p, std::ios::trunc);
99	    out << kDuplicateIds;
100	  }
101	  EXPECT_FALSE(reloader.Tick());                     // 校验失败，没有换新
102	  EXPECT_EQ(reloader.catalog().stations.size(), 3u); // 旧目录仍在
103	  EXPECT_FALSE(reloader.last_error().empty());
104	  std::remove(p.c_str());
